// Refreshes the /lookups/runbooks table (appci -> runbookCount) from Dynatrace
// notebooks. A notebook is counted as a runbook for an AppCI when its name
// starts with a 3-letter AppCI token AND contains the word "Runbook"
// (case-insensitive) anywhere. Mirrors the SLO-dashboards convention, but
// scans notebooks (documents API) instead of dashboards.
export default async function () {
  // 1. Page through all notebook documents
  const docs = [];
  let pageKey = null;
  do {
    const url = pageKey
      ? `/platform/document/v1/documents?page-key=${encodeURIComponent(pageKey)}`
      : `/platform/document/v1/documents?filter=${encodeURIComponent("type == 'notebook'")}&page-size=100`;
    const r = await fetch(url);
    if (!r.ok) {
      throw new Error(`List documents failed: ${r.status} ${await r.text()}`);
    }
    const j = await r.json();
    for (const d of (j.documents || [])) docs.push(d);
    pageKey = j.nextPageKey || null;
  } while (pageKey);

  // 2. Match runbooks and aggregate appci -> count.
  //    appci = leading 3-letter token (3 letters not followed by another letter),
  //    lowercased. Name must contain "runbook" (case-insensitive) anywhere.
  const counts = {};
  for (const d of docs) {
    const name = String((d && d.name) || '');
    if (!/runbook/i.test(name)) continue;
    const m = name.match(/^\s*([A-Za-z]{3})(?![A-Za-z])/);
    if (!m) continue;
    const appci = m[1].toLowerCase();
    counts[appci] = (counts[appci] || 0) + 1;
  }

  // 3. Build CSV (header is skipped on upload via skippedRecords:1).
  //    A loaded 0-row lookup exposes no columns, which would break the
  //    consuming DQL (FIELD_DOES_NOT_EXIST on `appci`). To keep the table's
  //    schema present even when nothing matches, always emit a sentinel row
  //    whose appci ("__none__") can never equal a real 3-letter AppCI, so it
  //    never joins to any scorecard row.
  const appcis = Object.keys(counts).sort();
  const rows = appcis.map((a) => `${a},${counts[a]}`);
  if (rows.length === 0) rows.push('__none__,0');
  const csv = 'appci,runbookCount\n' + rows.join('\n') + '\n';

  // 4. Upload as a lookup table (overwrite existing)
  const meta = {
    filePath: '/lookups/runbooks',
    displayName: 'Runbooks by AppCI',
    description: 'Count of Runbook notebooks per applicationCI, refreshed daily from the documents API',
    lookupField: 'appci',
    parsePattern: "LD:appci ',' LD:runbookCount",
    skippedRecords: 1,
    autoFlatten: true,
    timezone: 'UTC',
    locale: 'en_US',
    overwrite: true,
  };

  const boundary = '----runbooklookupboundary' + Date.now();
  const body =
    `--${boundary}\r\n` +
    `Content-Disposition: form-data; name="request"\r\n` +
    `Content-Type: application/json\r\n\r\n` +
    `${JSON.stringify(meta)}\r\n` +
    `--${boundary}\r\n` +
    `Content-Disposition: form-data; name="content"; filename="runbooks"\r\n` +
    `Content-Type: application/octet-stream\r\n\r\n` +
    `${csv}\r\n` +
    `--${boundary}--\r\n`;

  const resp = await fetch('/platform/storage/resource-store/v1/files/tabular/lookup:upload', {
    method: 'POST',
    headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}` },
    body,
  });

  const text = await resp.text();
  if (!resp.ok) {
    throw new Error(`Lookup upload failed: ${resp.status} ${text}`);
  }
  return { notebooksRead: docs.length, appciRows: appcis.length, counts };
}
